Um inventário simples pode usar um dicionário:

`python
inventario = {}

def adicionar_item(nome, quantidade=1):
    inventario[nome] = inventario.get(nome, 0) + quantidade

def remover_item(nome, quantidade=1):
    if nome not in inventario:
        return False

    if inventario[nome] < quantidade:
        return False

    inventario[nome] -= quantidade

    if inventario[nome] == 0:
