Uma colisão AABB simples pode ser detectada assim:

`js
function colidiu(a, b) {
    return (
        a.x < b.x + b.largura &&
        a.x + a.largura > b.x &&
        a.y < b.y + b.altura &&
        a.y + a.altura > b.y
    );
}

const jogador = {
    x: 10,
    y: 10,
    largura: 40,
    altura: 40
};

const inimigo = {
    x: 30,
    y: 30,
    largura: 40,
    altura: 40
};

console.log(colidiu(jogador, inimigo)); // true
`

