`cpp
#include <algorithm>
#include <iostream>
#include <vector>

int maior(const std::vector<int>& numeros) {
    if (numeros.empty()) {
        throw std::invalid_argument("Vetor vazio");
    }

    return *std::max_element(numeros.begin(), numeros.end());
}

int main() {
    std::vector<int> numeros = {4, 12, 7, 20, 3};
    std::cout << maior(numeros) << '\n';
}
