`js
class EventEmitter {
    constructor() {
        this.eventos = {};
    }

    on(nome, callback) {
        if (!this.eventos[nome]) {
            this.eventos[nome] = [];
        }

        this.eventos[nome].push(callback);
    }

    emit(nome, dados) {
        for (const callback of this.eventos[nome] ?? []) {
            callback(dados);
        }
    }
}

const eventos = new EventEmitter();

eventos.on("mensagem", texto => {
    console.log("Recebido:", texto);
});

