def bubble_sort(lista):
    lista = lista.copy()

    for fim in range(len(lista) - 1, 0, -1):
        trocou = False

        for i in range(fim):
            if lista[i] > lista[i + 1]:
                lista[i], lista[i + 1] = lista[i + 1], lista[i]
                trocou = True

        if not trocou:
