def segundo_maior(lista):
    maior = None
    segundo = None

    for valor in lista:
        if valor == maior:
            continue

        if maior is None or valor > maior:
            segundo = maior
            maior = valor
        elif segundo is None or valor > segundo:
            segundo = valor

    if segundo is None:
