`python
def fatorial(n):
    if n < 0:
        raise ValueError("O número deve ser não negativo")

    if n <= 1:
        return 1

    return n * fatorial(n - 1)

print(fatorial(5))  # 120
`

`python
def fibonacci(n):
    if n < 0:
        raise ValueError("n deve ser não negativo")

    a, b = 0, 1

    for _ in range(n):
        a, b = b, a + b

    return a

print(fibonacci(10))  # 55
`

